--
-- Table structure for table `player_equipment_slots`
--

DROP TABLE IF EXISTS `player_equipment_slots`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `player_equipment_slots` (
  `profile_name` varchar(18) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `owner_type` varchar(16) COLLATE utf8mb4_hungarian_ci NOT NULL DEFAULT 'player',
  `owner_id` varchar(64) COLLATE utf8mb4_hungarian_ci NOT NULL DEFAULT 'self',
  `slot_key` varchar(32) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `payload_json` longtext COLLATE utf8mb4_hungarian_ci NOT NULL,
  `updated_at` bigint NOT NULL,
  PRIMARY KEY (`profile_name`,`owner_type`,`owner_id`,`slot_key`),
  KEY `idx_equipment_profile_owner` (`profile_name`,`owner_type`,`owner_id`,`updated_at` DESC),
  CONSTRAINT `fk_player_equipment_player` FOREIGN KEY (`profile_name`) REFERENCES `players` (`profile_name`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_hungarian_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

