--
-- Table structure for table `player_notifications`
--

DROP TABLE IF EXISTS `player_notifications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `player_notifications` (
  `notification_id` varchar(128) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `profile_name` varchar(18) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `message_type` varchar(32) COLLATE utf8mb4_hungarian_ci NOT NULL DEFAULT 'event',
  `title` varchar(120) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `body` text COLLATE utf8mb4_hungarian_ci NOT NULL,
  `sender_profile_name` varchar(18) COLLATE utf8mb4_hungarian_ci DEFAULT NULL,
  `read_at` bigint DEFAULT NULL,
  `created_at` bigint NOT NULL,
  `payload_json` longtext COLLATE utf8mb4_hungarian_ci NOT NULL,
  `updated_at` bigint NOT NULL,
  PRIMARY KEY (`notification_id`),
  KEY `idx_player_notifications_profile` (`profile_name`,`created_at` DESC),
  KEY `idx_player_notifications_unread` (`profile_name`,`read_at`,`created_at` DESC),
  CONSTRAINT `fk_player_notifications_player` FOREIGN KEY (`profile_name`) REFERENCES `players` (`profile_name`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_hungarian_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

