--
-- Table structure for table `player_process_tasks`
--

DROP TABLE IF EXISTS `player_process_tasks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `player_process_tasks` (
  `task_id` varchar(128) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `profile_name` varchar(18) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `task_scope` varchar(16) COLLATE utf8mb4_hungarian_ci NOT NULL DEFAULT 'main',
  `slot_index` int NOT NULL DEFAULT '0',
  `task_type` varchar(32) COLLATE utf8mb4_hungarian_ci NOT NULL DEFAULT '',
  `task_status` varchar(24) COLLATE utf8mb4_hungarian_ci NOT NULL DEFAULT '',
  `ends_at` bigint DEFAULT NULL,
  `payload_json` longtext COLLATE utf8mb4_hungarian_ci NOT NULL,
  `updated_at` bigint NOT NULL,
