DROP TABLE IF EXISTS `player_world_rivals`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `player_world_rivals` (
  `city_id` varchar(128) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `profile_name` varchar(18) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `lot_id` varchar(64) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `city_status` varchar(24) COLLATE utf8mb4_hungarian_ci NOT NULL DEFAULT 'hostile',
  `city_level` int NOT NULL DEFAULT '1',
  `city_power` int NOT NULL DEFAULT '1',
  `tribute_ready_at` bigint DEFAULT NULL,
  `payload_json` longtext COLLATE utf8mb4_hungarian_ci NOT NULL,
  `updated_at` bigint NOT NULL,
  PRIMARY KEY (`city_id`),
  KEY `idx_player_world_rivals_profile` (`profile_name`,`updated_at` DESC,`lot_id`),
  CONSTRAINT `fk_player_world_rivals_player` FOREIGN KEY (`profile_name`) REFERENCES `players` (`profile_name`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_hungarian_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

